const server=app.listen(Number(process.env.PORT||4310),'127.0.0.1',()=>console.log('Santa Claw private installation is ready.'));securityTerminal.attach(server);process.on('SIGTERM',()=>{clearInterval(announcementTimer);clearInterval(factoryTimer);hackathon?.worker.cancel();factoryServer?.close();securityTerminal.close();challenges.stop();network.stop();server.close(()=>{db.close();process.exit(0);});setTimeout(()=>process.exit(0),5000).unref();});
